begin;
create table if not exists public.patient_referral_sources(id bigint generated by default as identity primary key,clinic_id bigint not null references public.clinics(id) on delete cascade,name text not null,color text not null default '#22c55e',referral_url text,description text,is_active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(clinic_id,name));
alter table public.customers add column if not exists referral_source_id bigint references public.patient_referral_sources(id) on delete set null;
alter table public.patient_referral_sources enable row level security;
drop policy if exists patient_referral_sources_scope on public.patient_referral_sources;
create policy patient_referral_sources_scope on public.patient_referral_sources for all to authenticated using(clinic_id=public.current_clinic_id()) with check(clinic_id=public.current_clinic_id());
grant select,insert,update,delete on public.patient_referral_sources to authenticated;grant usage,select on all sequences in schema public to authenticated;
drop view if exists public.customer_directory;
create or replace view public.customer_directory with (security_invoker=true) as select c.id,c.clinic_id,c.branch_id,c.customer_code,c.first_name,c.last_name,c.phone,c.phone_normalized,c.email,c.gender,c.status,c.date_of_birth,c.national_id,c.nationality,c.created_at,c.assigned_doctor_id,c.referral_source_id,coalesce(ref.name,c.referral_source) referral_source,c.referral_detail,c.selected_at,b.name branch_name,d.staff_name assigned_doctor_name,coalesce(fin.total_paid,0) total_paid,coalesce(fin.remaining,0) remaining,coalesce(wallet.balance,0) wallet_balance,coalesce(loyalty.points_balance,0) points_available,previous_appointment.appointment_at previous_appointment_at,previous_appointment.doctor_name previous_appointment_doctor,active_appointment.appointment_at active_appointment_at,active_appointment.doctor_name active_appointment_doctor,coalesce(tags.tags,'[]'::jsonb) tags from public.customers c left join public.branches b on b.id=c.branch_id left join public.staff d on d.id=c.assigned_doctor_id left join public.patient_referral_sources ref on ref.id=c.referral_source_id left join lateral(select sum(coalesce(p.paid_amount,case when p.payment_status='paid' then p.amount else 0 end)) total_paid,sum(coalesce(p.balance_due,0)) remaining from public.payments p where p.customer_id=c.id and p.payment_status not in('cancelled','refunded')) fin on true left join lateral(select sum(case when w.transaction_type in('credit','refund') then w.amount else -w.amount end) balance from public.patient_wallet_transactions w where w.customer_id=c.id) wallet on true left join public.patient_loyalty_accounts loyalty on loyalty.customer_id=c.id left join lateral(select a.appointment_at,coalesce(s.staff_name,a.doctor_name) doctor_name from public.appointments a left join public.staff s on s.id=a.doctor_id where a.customer_id=c.id and a.appointment_at<now() order by a.appointment_at desc limit 1) previous_appointment on true left join lateral(select a.appointment_at,coalesce(s.staff_name,a.doctor_name) doctor_name from public.appointments a left join public.staff s on s.id=a.doctor_id where a.customer_id=c.id and a.appointment_at>=now() and a.status not in('cancelled','no_show','completed') order by a.appointment_at limit 1) active_appointment on true left join lateral(select jsonb_agg(jsonb_build_object('id',t.id,'name',t.name,'color',t.color) order by t.name) tags from public.customer_patient_tags ct join public.patient_tags t on t.id=ct.tag_id where ct.customer_id=c.id and t.is_active) tags on true;
grant select on public.customer_directory to authenticated;
commit;
